with metrics as (select *, cume_dist() over w_ordered as amount_cume_dist, round(amount / sum(amount) over (partition by method, status), 4) as amount_share, row_number() over (partition by order_id order by amount, id) as seq_no, ntile(3) over (order by amount desc, id) as amount_bucket from payments window w_ordered as (partition by order_id order by amount nulls first)) select seq_no, count(distinct method) as distinct_methods, round(avg(amount_bucket), 2) as avg_amount_bucket, max(paid_at) as last_seen from metrics group by seq_no
